	/// check whether the metadata provided is aligned with this statically generated code.
	pub fn is_codegen_valid_for(metadata: &::subxt::Metadata) -> bool {
		let runtime_metadata_hash = metadata
			.hasher()
			.only_these_pallets(&PALLETS)
			.only_these_runtime_apis(&RUNTIME_APIS)
			.hash();
		runtime_metadata_hash ==
			[
				115u8, 165u8, 229u8, 99u8, 99u8, 109u8, 12u8, 18u8, 161u8, 132u8, 27u8, 86u8, 59u8,
				169u8, 87u8, 191u8, 226u8, 110u8, 75u8, 201u8, 235u8, 207u8, 163u8, 28u8, 67u8,
				34u8, 58u8, 233u8, 130u8, 226u8, 101u8, 199u8,
			]
	}
